import React from 'react';
import Item from './Item'; 
import './LibsAndFrameworks.css';

import reactIcon from '../../images/icons/react_icon.webp';
import nextJsIcon from '../../images/icons/nextjs_icon.png'; 
import numPy from '../../images/icons/numpy_icon.png'; 

const LibsAndFrameworks = () => {
  const language = [
    {
        title: "React",
        logo: reactIcon, 
    },
    {
        title: "Next.js",
        logo: nextJsIcon, 
    },
    {
        title: "NumPy",
        logo: numPy, 
    },
    {
        title: "Firebase",
        logo: reactIcon, 
    },    
    {
        title: "MatplotLib",
        logo: reactIcon, 
    },

    {
        title: "Junit",
        logo: reactIcon, 
    },
    {
        title: "pandas",
        logo: reactIcon, 
    },
  ];

  return (
    <div className="languages-container"> {}
      {language.map((lang) => (
        <Item
          key={lang.title} 
          title={lang.title}
          logo={lang.logo}
        />
      ))}
    </div>
  );
};

export default LibsAndFrameworks;
